#include <stdio.h>
#include <stdbool.h>
#include <string.h>

bool isSuffix(const long long *suffix, size_t suffix_len, const long long *arr, size_t arr_len) {
    if (suffix_len > arr_len) {
        return false;
    }
    for (size_t i = 0; i < suffix_len; i++) {
        if (suffix[i] != arr[arr_len - suffix_len + i]) {
            return false;
        }
    }
    return true;
}

int main() {
    long long test1_suffix[] = {2, 3};
    long long test1_arr[] = {1, 2, 3};
    printf("%s\n", isSuffix(test1_suffix, 2, test1_arr, 3) ? "true" : "false");

    long long test2_suffix[] = {4, 5};
    long long test2_arr[] = {1, 2, 3};
    printf("%s\n", isSuffix(test2_suffix, 2, test2_arr, 3) ? "true" : "false");

    long long test3_suffix[] = {};
    long long test3_arr[] = {1, 2, 3};
    printf("%s\n", isSuffix(test3_suffix, 0, test3_arr, 3) ? "true" : "false");

    long long test4_suffix[] = {3};
    long long test4_arr[] = {};
    printf("%s\n", isSuffix(test4_suffix, 1, test4_arr, 0) ? "true" : "false");

    long long test5_suffix[] = {};
