import java.util.Arrays;

public class Solution {
    public static boolean isSuffix(int[] suffix, int[] arr) {
        boolean result = true;
        int suffixLen = suffix.length;
        int arrLen = arr.length;

        if (suffixLen > arrLen) {
            result = false;
        } else {
            for (int i = 0; i < suffixLen; i++) {
                if (suffix[suffixLen - 1 - i] != arr[arrLen - 1 - i]) {
                    result = false;
                    break;
                }
            }
        }

        return result;
    }

    public static void main(String[] args) {
        int[] suffix1 = {2, 3};
        int[] arr1 = {1, 2, 3};
        System.out.println(isSuffix(suffix1, arr1));

        int[] suffix2 = {4, 5};
        int[] arr2 = {1, 2, 3};
        System.out.println(isSuffix(suffix2, arr2));

        int[] suffix3 = {};
        int[] arr3 = {1, 2, 3};
        System.out.println(isSuffix(suffix3, arr3));

        int[] suffix4 = {0, 0, 0};
        int[] arr4 = {0, 0, 0, 0};
        System.out.println(isSuffix(suffix4, arr4));

        int[] suffix5 = {5};
        int[] arr5 = {5};
        System.out.println(isSuffix(suffix5, arr5));

        int[] suffix6 = {3, 4, 5};
        int[] arr6 = {1, 2, 3, 4, 5};
        System.out.println(isSuffix(suffix6, arr6));
    }
}
